SET threads TO 1;
ATTACH 'test.db' (ROW_GROUP_SIZE 8192);
USE test;
CREATE TABLE flights (
    Year                            BIGINT,
    Quarter                         BIGINT,
    Month                           BIGINT,
    DayofMonth                      BIGINT,
    DayOfWeek                       BIGINT,
    FlightDate                      DATE,
    Reporting_Airline               VARCHAR,
    DOT_ID_Reporting_Airline        BIGINT,
    IATA_CODE_Reporting_Airline     VARCHAR,
    Tail_Number                     VARCHAR,
    Flight_Number_Reporting_Airline BIGINT,
    OriginAirportID                 BIGINT,
    OriginAirportSeqID              BIGINT,
    OriginCityMarketID              BIGINT,
    Origin                          VARCHAR,
    OriginCityName                  VARCHAR,
    OriginState                     VARCHAR,
    OriginStateFips                 VARCHAR,
    OriginStateName                 VARCHAR,
    OriginWac                       BIGINT,
    DestAirportID                   BIGINT,
    DestAirportSeqID                BIGINT,
    DestCityMarketID                BIGINT,
    Dest                            VARCHAR,
    DestCityName                    VARCHAR,
    DestState                       VARCHAR,
    DestStateFips                   VARCHAR,
    DestStateName                   VARCHAR,
    DestWac                         BIGINT,
    CRSDepTime                      VARCHAR,
    DepTime                         VARCHAR,
    DepDelay                        DOUBLE,
    DepDelayMinutes                 DOUBLE,
    DepDel15                        DOUBLE,
    DepartureDelayGroups            BIGINT,
    DepTimeBlk                      VARCHAR,
    TaxiOut                         DOUBLE,
    WheelsOff                       VARCHAR,
    WheelsOn                        VARCHAR,
    TaxiIn                          DOUBLE,
    CRSArrTime                      VARCHAR,
    ArrTime                         VARCHAR,
    ArrDelay                        DOUBLE,
    ArrDelayMinutes                 DOUBLE,
    ArrDel15                        DOUBLE,
    ArrivalDelayGroups              BIGINT,
    ArrTimeBlk                      VARCHAR,
    Cancelled                       DOUBLE,
    CancellationCode                VARCHAR,
    Diverted                        DOUBLE,
    CRSElapsedTime                  DOUBLE,
    ActualElapsedTime               DOUBLE,
    AirTime                         DOUBLE,
    Flights                         DOUBLE,
    Distance                        DOUBLE,
    DistanceGroup                   BIGINT,
    CarrierDelay                    DOUBLE,
    WeatherDelay                    DOUBLE,
    NASDelay                        DOUBLE,
    SecurityDelay                   DOUBLE,
    LateAircraftDelay               DOUBLE,
    FirstDepTime                    VARCHAR,
    TotalAddGTime                   DOUBLE,
    LongestAddGTime                 DOUBLE,
    DivAirportLandings              BIGINT,
    DivReachedDest                  DOUBLE,
    DivActualElapsedTime            DOUBLE,
    DivArrDelay                     DOUBLE,
    DivDistance                     DOUBLE,
    Div1Airport                     VARCHAR,
    Div1AirportID                   BIGINT,
    Div1AirportSeqID                BIGINT,
    Div1WheelsOn                    VARCHAR,
    Div1TotalGTime                  DOUBLE,
    Div1LongestGTime                DOUBLE,
    Div1WheelsOff                   VARCHAR,
    Div1TailNum                     VARCHAR,
    Div2Airport                     VARCHAR,
    Div2AirportID                   BIGINT,
    Div2AirportSeqID                BIGINT,
    Div2WheelsOn                    VARCHAR,
    Div2TotalGTime                  DOUBLE,
    Div2LongestGTime                DOUBLE,
    Div2WheelsOff                   BIGINT,
    Div2TailNum                     VARCHAR,
    Div3Airport                     VARCHAR,
    Div3AirportID                   VARCHAR,
    Div3AirportSeqID                VARCHAR,
    Div3WheelsOn                    VARCHAR,
    Div3TotalGTime                  VARCHAR,
    Div3LongestGTime                VARCHAR,
    Div3WheelsOff                   VARCHAR,
    Div3TailNum                     VARCHAR,
    Div4Airport                     VARCHAR,
    Div4AirportID                   VARCHAR,
    Div4AirportSeqID                VARCHAR,
    Div4WheelsOn                    VARCHAR,
    Div4TotalGTime                  VARCHAR,
    Div4LongestGTime                VARCHAR,
    Div4WheelsOff                   VARCHAR,
    Div4TailNum                     VARCHAR,
    Div5Airport                     VARCHAR,
    Div5AirportID                   VARCHAR,
    Div5AirportSeqID                VARCHAR,
    Div5WheelsOn                    VARCHAR,
    Div5TotalGTime                  VARCHAR,
    Div5LongestGTime                VARCHAR,
    Div5WheelsOff                   VARCHAR,
    Div5TailNum                     VARCHAR,
    column109                       VARCHAR,
);

PRAGMA enable_profiling='json';
PRAGMA profiling_output='profiler/tables/flights.json';
PRAGMA custom_profiling_settings = '{"STATISTICS_SIZE": "true"}';
COPY flights FROM 'flights/On_Time_Reporting_Carrier_On_Time_Performance_(1987_present)_2025_*.csv' (FORMAT 'csv', delimiter ',', header 1);
RESET custom_profiling_settings;
PRAGMA enable_profiling='json';
